/**
 * The last sync from the owner's phone while the session lasts (issue #697): asking (the phone shows a confirmation), sending (confirmed; the phone uploads), importing, done, or failed with its reason. messages were added in chats; skipped counts the chats that could not be read.
 */
export type PhoneSync = {
  stage: 'asking' | 'sending' | 'importing' | 'done' | 'failed';
  reason?: string;
  messages: number;
  chats: number;
  skipped: number;
  /**
   * When it got to its stage.
   */
  at: string;
};

/**
 * The session of a Connection of kind device, held by the control plane. logged_out needs a link again (sign_in_required is then true); disconnected comes back by itself; banned lasts until `until` when the service said; replaced is another client that opened the same session; outdated needs the control plane updated.
 */
export type DeviceSession = {
  state: 'connecting' | 'connected' | 'disconnected' | 'logged_out' | 'banned' | 'replaced' | 'outdated';
  /**
   * The service's own words for a ban or a logout, when it gave some.
   */
  reason?: string;
  /**
   * When a ban ends, when the service said.
   */
  until?: string;
  phone_sync?: PhoneSync;
};

/**
 * One action a Connection's account cannot do at the service, and why.
 */
export type ConnectionCannot = {
  /**
   * The action's name in commands, such as superset.logs.read.
   */
  action: string;
  service: string;
  name: string;
  /**
   * Why, such as role ServiceReader has no can_read on Log.
   */
  reason: string;
};

/**
 * An account of a service at an address of its own (address, username, password), an app of a service (app_id, app_secret), or a role of an AWS account (role_arn, key, and access_key_id with secret_access_key when the key is new or replaced).
 */
export type NewAccountConnection = {
  /**
   * The app's App ID, for an Integration that is an app. Not secret.
   */
  app_id?: string;
  /**
   * Where the service is, such as https://superset.example.com.
   */
  address?: string;
  /**
   * The proxy the address is reached through, signing in included (issue #850). Absent keeps the one the label has.
   */
  proxy?: string;
  /**
   * Where the address is dialed instead of its host's, as curl's --resolve (issue #850). Absent keeps the one the label has.
   */
  dial_address?: string;
  username?: string;
  /**
   * The ARN of the role, such as arn:aws:iam::123456789012:role/hypomnema/read.
   */
  role_arn?: string;
  /**
   * The name the key that assumes the role is kept under, such as main.
   */
  key?: string;
  access_key_id?: string;
};

