export type GatewayUsageCounts = {
  requests: number;
  /**
   * The web searches: each web/search answered, and the searches models made themselves (Anthropic's server_tool_use.web_search_requests, the Responses API's web_search_call items).
   */
  web_searches: number;
  /**
   * The seconds of recordings transcriptions heard.
   */
  audio_seconds: number;
  /**
   * The characters speech spoke.
   */
  characters: number;
  /**
   * The images image requests made.
   */
  images: number;
  /**
   * What the priced requests cost at their vendor's API price, in micro-dollars; for a subscription, what the same tokens would cost at the API, not what the plan costs.
   */
  cost_micros: number;
  /**
   * The requests with tokens, searches, seconds or characters that the price book has no price for.
   */
  unpriced: number;
  /**
   * The requests the provider refused, none answered, or whose answer ended early.
   */
  failed: number;
  /**
   * Tokens in, those read from the provider's cache included.
   */
  prompt_tokens: number;
  cached_tokens: number;
  completion_tokens: number;
  reasoning_tokens: number;
};

export type GatewayUsageBucket = {
  start: string;
  counts: GatewayUsageCounts;
};

export type GatewayUsageGroup = {
  /**
   * The key's or the account's id; for a model, its name.
   */
  id: string;
  /**
   * The model's or the key's name, or the account's label; empty for an account since removed.
   */
  name: string;
  /**
   * An account's runtime (claude, codex, antigravity, opencode_go).
   */
  runtime?: string;
  counts: GatewayUsageCounts;
};

/**
 * The speed and reliability of a provider's model, or of a subscription account, over the requests to the text models. Time to first token is over the answered streams, latency over the answered requests, tokens a second (output tokens over the time after the first token) over the answered streams whose tokens were reported.
 */
export type GatewayPerformance = {
  provider: string;
  /**
   * The model the provider served; empty for an account.
   */
  model: string;
  account_id?: string;
  account_label?: string;
  /**
   * An account's runtime (claude, codex, antigravity).
   */
  runtime?: string;
  requests: number;
  ok: number;
  failed: number;
  /**
   * The requests whose client left first; they count neither as answered nor as failed.
   */
  client_gone: number;
  /**
   * Requests refused by the gateway because all usable accounts were cooling.
   */
  no_account: number;
  /**
   * The answered share of answered and failed requests, 0 to 1; absent when there is none.
   */
  success_rate?: number;
  cost_micros: number;
  /**
   * Read from each request, with percentiles and the median tokens a second; false from the ledger.
   */
  exact: boolean;
  ttft_p50_ms?: number;
  ttft_p95_ms?: number;
  latency_p50_ms?: number;
  latency_p95_ms?: number;
  ttft_avg_ms?: number;
  latency_avg_ms?: number;
  /**
   * The median of the requests' output tokens a second; from the ledger, all tokens over all time.
   */
  tokens_per_second?: number;
};

export type GatewayUsage = {
  /**
   * Read from the daily ledger (90d, 12m): UTC days, the owner's keys counted together as the key "owner", and no percentiles.
   */
  ledger: boolean;
  by_provider: Array<GatewayPerformance>;
  speed_by_account: Array<GatewayPerformance>;
  since: string;
  until: string;
  /**
   * How long a bar is, an hour or a day.
   */
  bucket_seconds: number;
  totals: GatewayUsageCounts;
  buckets: Array<GatewayUsageBucket>;
  by_model: Array<GatewayUsageGroup>;
  by_key: Array<GatewayUsageGroup>;
  by_account: Array<GatewayUsageGroup>;
};

export type GatewayRequest = {
  id: string;
  created_at: string;
  key_id: string;
  key_name: string;
  /**
   * The name the client asked for.
   */
  model: string;
  /**
   * Where the last attempt went.
   */
  provider: string;
  upstream_model: string;
  /**
   * The subscription account of the last attempt; absent for an API provider.
   */
  account_id?: string;
  account_label?: string;
  stream: boolean;
  attempts: number;
  outcome: 'ok' | 'upstream_error' | 'transport_error' | 'truncated' | 'client_gone' | 'no_account';
  /**
   * The provider's HTTP status, or 429 for a gateway account refusal; 0 when no status was recorded.
   */
  status: number;
  /**
   * The provider's error or the gateway's reason for refusing the request.
   */
  error?: string;
  prompt_tokens: number;
  cached_tokens: number;
  completion_tokens: number;
  reasoning_tokens: number;
  /**
   * The part of the tokens in written to the provider's cache.
   */
  cache_write_tokens: number;
  /**
   * The part of the cache write that lasts an hour (Anthropic's), priced at its own rate.
   */
  cache_write_1h_tokens: number;
  /**
   * The cost at the vendor's API price, in micro-dollars: its tokens, searches, seconds or characters, at the price of each (LiteLLM's price map for those not counted in tokens); absent when there is none.
   */
  cost_micros?: number;
  /**
   * The model the cost was priced as.
   */
  priced_model?: string;
  /**
   * The provider reported no usage; the counts are the sizes divided by four.
   */
  estimated: boolean;
  duration_ms: number;
  /**
   * Time to first token: from the gateway receiving the request to the first chunk it streamed to the client; absent for an answer that is not a stream.
   */
  ttft_ms?: number;
  /**
   * The output tokens over the time after the first token; absent when the request was not a stream, its counts were estimated, or it had no output.
   */
  tokens_per_second?: number;
  /**
   * The seconds of the recording an audio transcription heard; absent for other requests.
   */
  audio_seconds?: number;
  /**
   * The characters an audio speech request spoke; absent for other requests.
   */
  characters?: number;
  /**
   * The web searches the request made: 1 for an answered web/search, and a model's own searches beside its tokens; absent when none.
   */
  web_searches?: number;
  /**
   * The images an image request made; absent for other requests.
   */
  images?: number;
};

