export type SkillFromGitHub = {
  /**
   * owner/repo[/path][@ref]; no ref is the default branch.
   */
  github: string;
  /**
   * The name of a skill in the repository, as skills.sh gives it, instead of a path: the folder whose SKILL.md has this name is found as the skills CLI finds it, and kept as the source's path.
   */
  skill?: string;
};

export type SkillEveryone = {
  everyone: boolean;
};

export type ToolNames = {
  data: Array<string>;
};

export type Bot = {
  /**
   * The Bot's id, which never changes; every record that names the Bot names this.
   */
  id: string;
  /**
   * What the Bot is called; shown, and changed with a rename.
   */
  name: string;
  /**
   * The main Bot: always there, never removed, a chat that names no Bot talks with it, and it alone changes Bots and profiles from its chat.
   */
  main: boolean;
  /**
   * The Bot's place in the order the owner sets, 0 first (issue #470); the main Bot is first.
   */
  position: number;
  /**
   * Listed in the sidebar's Pinned section, under the main Bot.
   */
  pinned: boolean;
  provider?: string;
  model?: string;
  /**
   * Ordered gateway models (provider/model), tried when accounts cannot serve the inherited model.
   */
  fallbacks: Array<string>;
  effort?: string;
  /**
   * What the Bot is and how it behaves, written by the owner; pi gets it after its built-in instructions.
   */
  persona: string;
  /**
   * What the Bot keeps across chats, one entry per line.
   */
  memory: string;
  /**
   * The most characters the memory holds.
   */
  memory_limit: number;
  /**
   * The skills the Bot gets beside those given to everyone.
   */
  skills: Array<string>;
  /**
   * The skills given to everyone that the Bot does not get.
   */
  skills_off: Array<string>;
  preset: ToolPreset;
  tool_access?: ToolAccess;
  /**
   * Additional Hypomnema tools or families on top of the preset. The CLI's own tools are not switched here.
   */
  tools: Array<string>;
  /**
   * The Hypomnema tools the Bot's pi never gets, each a name or a family; it wins over tools.
   */
  tools_off: Array<string>;
  connections: AllowList;
  workers: AllowList;
  /**
   * What the Bot may reach of a Connection it may use, keyed integration:label: of a Superset Connection, the dashboards it may read. A Connection not named here is reached whole.
   */
  scopes: {
    [key: string]: ConnectionScope;
  };
  tool_display: ToolDisplay;
  /**
   * The Bot's guaranteed share of the room, in unsettled Dispatches of the Runs it made, across every node (issue #731; its limit, max_dispatches, until 2026-11-17). 4 unless the Bot sets its own. It is a first claim on room as room frees, not a cap: the Bot may use any free room the others do not need, and nothing running is stopped for it.
   */
  guaranteed_dispatches: number;
  created_at: string;
  updated_at: string;
};

/**
 * What the Bot's chats show of its tool calls, to everyone who reads them, on the web and at Lark: off, none, only its answers; on, a row per call with its tool's name; full, each call's arguments, output, error and time as well. The chat messages and the stream leave out what the level hides.
 */
export type ToolDisplay = 'off' | 'on' | 'full';

/**
 * The part of a Connection a Bot may reach. For Superset, the dashboards it may read, by number, and none when the list is empty; such a Bot reads only through the dashboards, dashboard and chart reads, and is refused the API relay for that Connection.
 */
export type ConnectionScope = {
  dashboards: Array<number>;
};

/**
 * What a Bot may use. Not limited, it may use every one; limited, only those named, and none when no name is.
 */
export type AllowList = {
  limited: boolean;
  names: Array<string>;
};

/**
 * A change of a Bot or a profile the main Bot made from a chat.
 */
export type SetupChange = {
  id: string;
  chat_id: string;
  kind: 'bot' | 'profile';
  /**
   * The profile's name, or the Bot's id for a Bot.
   */
  name: string;
  action: 'made' | 'changed' | 'removed';
  /**
   * An undo would be taken now.
   */
  can_undo: boolean;
  /**
   * Why it cannot be undone.
   */
  problem?: string;
  created_at: string;
  undone_at?: string;
};

export type SetupChangeList = {
  data: Array<SetupChange>;
};

/**
 * on: it runs by its schedule. paused: it does not, by the owner or after repeated failures.
 */
export type RoutineState = 'on' | 'paused';

export type RoutineKind = 'prompt' | 'script';

/**
 * Work a Bot does on a schedule: a prompt the Bot works on with its model in a new chat, or a script that runs with the Bot's tools and no model. A prompt Routine may have a script that runs first and wakes the Bot only when it finds work.
 */
export type Routine = {
  id: string;
  /**
   * The id of the Bot whose Routine it is.
   */
  bot: string;
  name: string;
  kind: RoutineKind;
  /**
   * What a prompt Routine gives its Bot.
   */
  prompt?: string;
  /**
   * The file a script Routine runs, or a prompt Routine runs first as a check, under the Bot's routines directory.
   */
  script?: string;
  /**
   * What the script's file holds.
   */
  script_text?: string;
  every_minutes?: number;
  cron?: string;
  timezone?: string;
  /**
   * The schedule in words: every hour.
   */
  schedule: string;
  /**
   * One sentence that restates the schedule and the work.
   */
  sentence: string;
  /**
   * A script's limit; 3600 for a prompt Routine without one.
   */
  timeout_seconds: number;
  state: RoutineState;
  paused_reason?: string;
  /**
   * What the work is, in the words of whoever made it.
   */
  summary?: string;
  /**
   * The chat it was made in.
   */
  chat_id?: string;
  /**
   * A run's answer or a script's output goes to the chat it was made in.
   */
  announce: boolean;
  next_run_at?: string;
  /**
   * The runs that failed in a row.
   */
  failures: number;
  /**
   * The due times that passed while a run was still going; they have no run of their own.
   */
  skipped: number;
  last_skipped_at?: string;
  /**
   * owner or bot.
   */
  created_by: string;
  /**
   * The last change was a Bot's and can be undone.
   */
  can_undo: boolean;
  created_at: string;
  updated_at: string;
  last_run?: RoutineRun;
  /**
   * What the owner allowed this Routine always.
   */
  grants: Array<RoutineGrant>;
};

export type RoutineList = {
  data: Array<Routine>;
};

export type RoutineSettings = {
  kind: RoutineKind;
  prompt?: string;
  /**
   * A file name, never a path or a command line. With a prompt, the script runs first: when it prints nothing, or its last line is {"wakeAgent": false}, the run ends succeeded with no chat; otherwise the Bot is woken with what it printed before the prompt.
   */
  script?: string;
  script_text?: string;
  every_minutes?: number;
  /**
   * Five fields; needs timezone.
   */
  cron?: string;
  /**
   * An IANA time zone, such as Asia/Ho_Chi_Minh.
   */
  timezone?: string;
  /**
   * How long a script, or a prompt's check, may run; 600 when absent. A prompt run works for at most an hour.
   */
  timeout_seconds?: number;
  summary?: string;
  /**
   * The chat the Routine is made in; a Bot names the chat it works in.
   */
  chat_id?: string;
  /**
   * Whether a run's result goes to that chat; it does when absent.
   */
  announce?: boolean;
  /**
   * The Routine whose run asks, when one does; it is refused.
   */
  from_routine?: string;
};

export type RoutineUndone = {
  /**
   * The Routine was one the Bot made and is gone.
   */
  removed: boolean;
  routine?: Routine;
};

export type RoutineLaunchRequest = {
  /**
   * The id of the Bot the Routine must belong to.
   */
  bot: string;
};

export type RoutineScriptLaunch = {
  script: string;
  script_text: string;
  timeout_seconds: number;
  /**
   * The run's key, given once.
   */
  key: string;
};

export type RoutineRun = {
  id: string;
  routine_id: string;
  /**
   * By the schedule or by hand.
   */
  started_by: 'schedule' | 'manual';
  /**
   * waiting is waiting for the owner's answer to an Approval; canceled is ended by his no, or by the Routine's removal.
   */
  state: 'running' | 'waiting' | 'succeeded' | 'failed' | 'canceled';
  started_at: string;
  ended_at?: string;
  /**
   * A script's exit code.
   */
  exit_code?: number;
  /**
   * The end of what a script printed, or a prompt run's answer.
   */
  output: string;
  error: string;
  /**
   * A prompt run's chat.
   */
  chat_id?: string;
};

export type RoutineRunList = {
  data: Array<RoutineRun>;
  /**
   * How many runs the Routine has.
   */
  total: number;
  /**
   * The offset of the next page; absent on the last.
   */
  next_offset?: number;
};

export type RoutineSchedule = {
  every_minutes?: number;
  cron?: string;
  timezone?: string;
};

export type RoutineSchedulePreview = {
  /**
   * The schedule in words: every weekday at 7:00 Ho Chi Minh time.
   */
  schedule: string;
  next: Array<string>;
};

/**
 * An action of a Connection that passes in the Routine's runs without asking.
 */
export type RoutineGrant = {
  integration: string;
  label: string;
  action: string;
  action_name: string;
  created_at: string;
};

